// =============================================================================
// The MDM key of a tenant (docs: integration-apple-edge §6.1, EX-02): opaque,
// generated by apple-edge (ids.NewTenantKey), 16 characters of its alphabet:
// lower-case letters and digits without l, o, 0 nor 1. The only reference to
// a tenant in the devices' URLs. Pure: the unit tests load it.
// =============================================================================

/** apple-edge's alphabet of the tenant keys. */
export const MDM_KEY_ALPHABET = 'abcdefghijkmnpqrstuvwxyz23456789';

/** A well-formed MDM key (also the CHECK of tenants.mdm_key and of obligarth.tenant_set_mdm_key). */
export const MDM_KEY_RE = /^[a-km-np-z2-9]{16}$/;

export function isMdmKey(value: unknown): value is string {
  return typeof value === 'string' && MDM_KEY_RE.test(value);
}
